steps.script:
var shooter := "U_TANKBUSTAS_A"
var blocked := [Vector2(620, 1620), Vector2(660, 1620), Vector2(700, 1620), Vector2(740, 1620)]
var u = GameState.state["units"][shooter]
u["models"][0]["position"] = {"x": 560.0, "y": 1620.0}
for i in range(1, 5):
	u["models"][i]["position"] = {"x": blocked[i - 1].x, "y": blocked[i - 1].y}
u["models"][5]["position"] = {"x": 300.0, "y": 2280.0}
for m in u["models"]:
	m["alive"] = true
u["flags"] = {}
var tgt = GameState.state["units"]["U_WITCHSEEKERS_C"]
var tx = [640.0, 680.0, 720.0, 760.0]
for i in range(tgt["models"].size()):
	tgt["models"][i]["position"] = {"x": tx[i], "y": 2280.0}
	tgt["models"][i]["alive"] = true
GameState.state["units"]["U_BLADE_CHAMPION_A"]["models"][0]["position"] = {"x": 300.0, "y": 200.0}
GameState.state["units"]["U_CALADIUS_GRAV-TANK_E"]["models"][0]["position"] = {"x": 1600.0, "y": 200.0}
PhaseManager.transition_to_phase(8)
return "geometry set"

var board = PhaseManager.get_current_phase_instance().game_state_snapshot
var e = RulesEngine.get_eligible_shooter_models("U_TANKBUSTAS_A", "rokkit_launcha_ranged", "U_WITCHSEEKERS_C", board)
return (e["eligible"] as Array).size()

var d = tree.root.get_node_or_null("PulsaRokkitDialog")
if d == null:
	return "no dialog"
var b = d.find_child("DeclineButton", true, false)
if b == null:
	return "no button"
b.emit_signal("pressed")
return "declined"

var ph = PhaseManager.get_current_phase_instance()
for a in ph.pending_assignments:
	if a.get("weapon_id", "") == "rokkit_launcha_ranged":
		return (a.get("model_ids", []) as Array).size()
return -1

var sc = tree.current_scene.get_node_or_null("ShootingController")
var root = sc.weapon_tree.get_root()
var c = root.get_first_child()
while c:
	if str(c.get_metadata(0)) == "rokkit_launcha_ranged":
		return c.get_text(1)
	c = c.get_next()
return "row not found"

var sc = tree.current_scene.get_node_or_null("ShootingController")
var txt = sc.blocked_bearers_label.get_parsed_text()
if txt.find("Rokkit launcha \u2014 only 1 of 5 will shoot") == -1:
	return "missing headline: " + txt
if txt.find("4 no line of sight") == -1:
	return "missing reason: " + txt
return "ok"

var sc = tree.current_scene.get_node_or_null("ShootingController")
for i in range(sc.target_basket.item_count):
	var t = sc.target_basket.get_item_text(i)
	if t.find("Rokkit launcha") != -1:
		return t.begins_with("1\u00d7 ")
return false

var sc = tree.current_scene.get_node_or_null("ShootingController")
var txt = sc.damage_preview_label.get_parsed_text()
if txt.find("Atk   2.0") == -1:
	return "forecast should cost ONE bearer (A:D3 avg 2.0), got: " + txt
return "ok"

var u = GameState.state["units"]["U_TANKBUSTAS_A"]
var xs = [200.0, 260.0, 320.0, 380.0, 440.0, 500.0]
for i in range(u["models"].size()):
	u["models"][i]["position"] = {"x": xs[i], "y": 2280.0}
u["flags"] = {}
PhaseManager.transition_to_phase(8)
return "all clear"

var d = tree.root.get_node_or_null("PulsaRokkitDialog")
if d == null:
	return "no dialog"
var b = d.find_child("DeclineButton", true, false)
if b == null:
	return "no button"
b.emit_signal("pressed")
return "declined"

var ph = PhaseManager.get_current_phase_instance()
for a in ph.pending_assignments:
	if a.get("weapon_id", "") == "rokkit_launcha_ranged":
		return (a.get("model_ids", []) as Array).size()
return -1
